import{_ as e,o,c as s,a2 as r}from"./chunks/framework.9yf7n3zg.js";const a="/guide/media/settings-appearance.webp",n="/guide/media/settings-storage.webp",d="/guide/media/settings-purge-dialog.webp",h="/guide/media/settings-mate.webp",f=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"reference/settings.md","filePath":"reference/settings.md","lastUpdated":1791677002000}'),i={name:"reference/settings.md"};function g(l,t,c,u,p,m){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>The Settings page holds the app&#39;s preferences, the open home&#39;s storage and author details, the mate, search, agents, keys and updates, and a door to each story&#39;s own settings. This page lists every section and every field in the order the page shows them, with its default and where it is kept: on this computer only, or in your writing home, where it travels with your stories.</p><h2 id="opening-settings" tabindex="-1">Opening Settings <a class="header-anchor" href="#opening-settings" aria-label="Permalink to &quot;Opening Settings&quot;">​</a></h2><ul><li><strong>Settings</strong> at the foot of the sidebar;</li><li><code>Ctrl+,</code> (<code>Cmd+,</code> on macOS);</li><li><strong>Settings</strong> in the <strong>File</strong> menu, or in the find field.</li></ul><p><strong>Back to Library</strong> at the foot of the section list, or <code>Esc</code>, goes back.</p><p><img src="'+a+'" alt="The Settings page open at Appearance, with the section list on the left and the file it writes named at the top right" width="1130" height="852" loading="lazy"></p><h2 id="how-the-page-is-laid-out" tabindex="-1">How the page is laid out <a class="header-anchor" href="#how-the-page-is-laid-out" aria-label="Permalink to &quot;How the page is laid out&quot;">​</a></h2><p>On the left, the sections. The first heading is the open home (&quot;Home · Sample&quot;), or <strong>App</strong> when no home is open. A section may show a short summary at the right of its name (&quot;dark&quot;, &quot;100%&quot; for the zoom, the number of style checks on, &quot;250 wpm&quot;, &quot;500/day&quot;, the number of keys, the agents connected, the version, the number of conflicted copies), and a dot when something needs you: conflicted copies in Storage, a newer version in Updates, refusals you have not seen in Agents.</p><p>Under <strong>Story</strong>, a menu picks one of the home&#39;s stories, followed by its two sections, <strong>Structure and goals</strong> and <strong>Export</strong>.</p><p>On the right, the section you picked. Its title sits at the top with, at the far right, the file that section writes, such as <code>preferences.json</code> or <code>suite/Author.json</code>. Changes apply as you make them; there is no Save button.</p><p>At the foot of most sections:</p><ul><li><strong>Export preferences…</strong> saves a copy of your preferences as a file you choose (<code>leathercase-preferences.json</code> by default).</li><li><strong>Reset this section</strong> puts the section back to its defaults. It is offered in Appearance, Accessibility, Lenses, Manuscript, New stories, Kind colours, Hotkeys (the global keys only) and Updates.</li></ul><p>With no home open, Storage, Sources and Author are not shown.</p><h2 id="where-preferences-are-kept" tabindex="-1">Where preferences are kept <a class="header-anchor" href="#where-preferences-are-kept" aria-label="Permalink to &quot;Where preferences are kept&quot;">​</a></h2><p>Some settings belong to this computer, some to the writing home.</p><table tabindex="0"><thead><tr><th>Kept</th><th>What</th><th>Where</th></tr></thead><tbody><tr><td>This computer only</td><td>The app&#39;s language, theme, appearance, accessibility (zoom, contrast, colour-blind colours, reduced motion), lenses, manuscript layout, the daily goal for new stories, kind colours, the mate&#39;s settings, the global keys, update checks, whether the sidebar, the mate&#39;s panel and the assistant&#39;s layer were open, where you left each story</td><td><code>preferences.json</code> in the app&#39;s data</td></tr><tr><td>This computer only</td><td>Your changes to keys</td><td><code>keybindings.json</code> in the app&#39;s data</td></tr><tr><td>This computer only</td><td>Connected agents, their tokens and grants</td><td><code>agents.json</code> and <code>agents/</code> in the app&#39;s data</td></tr><tr><td>This computer only</td><td>What the mate told and what you saw; the meaning model</td><td><code>mate/</code> and <code>models/</code> in the app&#39;s data</td></tr><tr><td>The writing home</td><td>The home&#39;s name, and its tile&#39;s colour and icon</td><td><code>suite/Library.json</code> at the home&#39;s root</td></tr><tr><td>The writing home</td><td>The author&#39;s name, contact and pen names</td><td><code>suite/Author.json</code> at the home&#39;s root</td></tr><tr><td>The writing home</td><td>Each story&#39;s settings, export settings and the app it opens in</td><td><code>suite/Story.json</code> and <code>suite/Export.json</code> in the story&#39;s folder</td></tr><tr><td>The writing home</td><td>How each story&#39;s plot grid, threads chart, beat board and graph tabs are laid out</td><td><code>GridLayout.json</code>, <code>Threads.json</code>, <code>BeatBoard.json</code> and <code>Graph/</code> in the story&#39;s <code>suite/</code> folder, so they travel with the story</td></tr></tbody></table><p>The app&#39;s data is a folder the system gives Leathercase:</p><table tabindex="0"><thead><tr><th>System</th><th>The app&#39;s data</th></tr></thead><tbody><tr><td>Linux</td><td><code>~/.config/Leathercase/data</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/Leathercase/data</code></td></tr><tr><td>Windows</td><td><code>%APPDATA%\\Leathercase\\data</code></td></tr></tbody></table><p>What is in the writing home syncs with it, if a sync tool carries the folder, and is readable without Leathercase. What is in the app&#39;s data stays on this computer; a second computer has its own. See <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>The open home: where it lives and who carries it. &quot;Leathercase reads the folder and never uploads anything itself.&quot; Writes <code>preferences.json</code>.</p><p><strong>This home</strong> comes first: the home&#39;s <strong>Name</strong>, as the switcher shows it, saved on Enter or when you leave the field; its tile&#39;s <strong>Color</strong>, one of nine or the accent; and its <strong>Icon</strong>, one of 24 or the name&#39;s first letter. They are kept in the home&#39;s <code>suite/Library.json</code> and sync with it. Right after you add a folder whose name another home has, a line here says what it was named and why.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it shows or does</th></tr></thead><tbody><tr><td><strong>Writing home</strong></td><td>The home&#39;s folder, and <strong>Show folder</strong>, which opens it in your file manager</td></tr><tr><td><strong>Sync</strong></td><td>Whether a sync tool carries the folder: &quot;local&quot; (&quot;No sync tool holds this folder; it lives on this computer only.&quot;) or &quot;detected&quot; with the tool&#39;s name (&quot;Dropbox carries this folder. Leathercase never uploads anything itself.&quot;)</td></tr><tr><td><strong>Daily snapshots</strong></td><td>A copy of every <code>suite/</code> folder, kept in <code>suite/daily</code> for 14 days; manuscripts are never copied. Shows how many days are kept and their size, the latest day, and <strong>Show</strong>, which opens the folder</td></tr></tbody></table><p><img src="'+n+'" alt="Settings › Storage for the home Sample: its folder, sync, daily snapshots and what Leathercase keeps in it" width="1130" height="852" loading="lazy"></p><p><strong>In this home</strong> lists what Leathercase keeps in the home&#39;s folder:</p><table tabindex="0"><thead><tr><th>Entry</th><th>What it is</th></tr></thead><tbody><tr><td><code>Suite.md</code></td><td>Marks this folder as a writing home and lists its stories. Leathercase rewrites only that list; the rest of the note is yours</td></tr><tr><td><code>suite/</code></td><td>The home&#39;s own structured files: its manifest, the author and pen names, the Writer board&#39;s layout, and the daily snapshots</td></tr><tr><td><code>Writer/</code></td><td>Your cards, one markdown note each, shared by every story in this home. If you chose another author data folder for the cards, its name comes first</td></tr><tr><td><code>4 × suite/</code></td><td>One inside each story&#39;s folder: its settings, export, layouts and snapshots as JSON, its Graph as markdown; its plot grid in <code>PlotGrid.md</code>, its threads, comments and beat cards as markdown; its writing and sentence logs as JSON Lines in <code>logs/</code></td></tr></tbody></table><p><strong>Other homes</strong> lists the other writing homes on this computer, each with its folder, <strong>Switch</strong> and <strong>Remove…</strong>. With none: &quot;No other home. A second home, for a pen name or another set of stories, adds a switcher to the navigation.&quot; <strong>Add a writing home…</strong> opens a folder.</p><h3 id="remove-this-home" tabindex="-1">Remove this home <a class="header-anchor" href="#remove-this-home" aria-label="Permalink to &quot;Remove this home&quot;">​</a></h3><p>Two ways to take a home off this computer. Both open a dialog with a <strong>Delete</strong> and <strong>Purge</strong> switch at its top, so you can change your mind there.</p><table tabindex="0"><thead><tr><th>Choice</th><th>What it does</th><th>What stays</th></tr></thead><tbody><tr><td><strong>Delete writing home</strong> (<strong>Delete…</strong>)</td><td>Takes the home off this computer&#39;s list, with what this computer kept of it: the passage to resume, the capture target, the agents&#39; access</td><td>Everything in the folder. Open the folder again to take the home up where you left it</td></tr><tr><td><strong>Purge writing home</strong> (<strong>Purge…</strong>)</td><td>Deletes the home from this computer and moves every file Leathercase made in the folder to the system&#39;s trash: its records, and the cards and notes you made in Leathercase</td><td>Your manuscripts and your own notes</td></tr></tbody></table><p>For <strong>Purge</strong>, the dialog lists what <strong>Moves to the trash</strong> and what is <strong>Left where they are</strong> (folders you chose for a story&#39;s notes, which may hold your own notes too, so Leathercase leaves them). If a sync tool carries the folder, it warns that these files will leave every device that syncs it. You must type the home&#39;s name to confirm before <strong>Purge home</strong> is enabled. <strong>Delete home</strong> needs no typing.</p><p><img src="'+d+'" alt="The Purge dialog for the home Sample, listing the files that move to the trash and asking for the home&#39;s name" width="640" height="605" loading="lazy"></p><h3 id="conflicted-copies" tabindex="-1">Conflicted copies <a class="header-anchor" href="#conflicted-copies" aria-label="Permalink to &quot;Conflicted copies&quot;">​</a></h3><p>When a sync tool keeps two versions of one of Leathercase&#39;s files, Storage lists them under <strong>Conflicts · N</strong>, and a dot appears on <strong>Storage</strong>. Each row names the story, or <strong>Home</strong> or <strong>Writer</strong>, and the file, with where the copy came from, when each side changed, and how far apart they are (&quot;3 values differ&quot;, &quot;1 line differs&quot;, &quot;the same&quot;, &quot;the original is gone&quot;).</p><ul><li><strong>Compare</strong> opens both sides in a table, by value for structured files and by line for markdown: <strong>This computer</strong> and <strong>The copy</strong>. When they are the same it says &quot;The two are the same; keep either.&quot;</li><li><strong>Keep the copy</strong> replaces this computer&#39;s version with the copy.</li><li><strong>Keep this computer&#39;s</strong> keeps yours and lets the copy go.</li></ul><p>&quot;The side you let go of goes to the system&#39;s trash, so nothing is lost. Leathercase only reads its own files here; your manuscripts are the sync tool&#39;s to reconcile.&quot; With none: &quot;No conflicted copies. When a sync tool keeps two versions of one of Leathercase&#39;s files, both appear here.&quot;</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>What each story is read from, and the app its passages open in. &quot;Every source is read-only: edits happen in the source.&quot; Read from the files.</p><p>One row per story, with its number of files (&quot;12 files · read-only&quot;), a badge for the source format, and a menu <strong>Open … in</strong>:</p><table tabindex="0"><thead><tr><th>The menu shows</th><th>Meaning</th></tr></thead><tbody><tr><td>&quot;Scrivener · inferred&quot; (dashed)</td><td>Leathercase guessed the app, with its reason</td></tr><tr><td>&quot;… · for the format&quot;</td><td>The app you chose for every story of this format</td></tr><tr><td><strong>Choose…</strong> (amber)</td><td>Leathercase could not tell; pick one</td></tr><tr><td>An app&#39;s name (solid)</td><td>Your choice, kept with the story</td></tr><tr><td><strong>Your default app</strong></td><td>The system&#39;s default</td></tr></tbody></table><p>The app for every story of one format is set from the manuscript&#39;s first <strong>Open in</strong>. A story not read yet says &quot;not read yet&quot;. With no story: &quot;No stories yet. Declare one from the Library.&quot;</p><h2 id="author" tabindex="-1">Author <a class="header-anchor" href="#author" aria-label="Permalink to &quot;Author&quot;">​</a></h2><p>Contact details for title pages and cover letters. &quot;Contact details stay in the home and only appear in exports.&quot; Writes <code>suite/Author.json</code> in the home.</p><p><strong>For title pages and cover letters</strong>: <strong>Legal name</strong> (top left of the title page), <strong>Address</strong> (one line per line), <strong>Email</strong>, <strong>Phone</strong>. <strong>Add agent…</strong> adds a literary agent&#39;s block, <strong>Agent&#39;s name</strong>, <strong>Agency</strong>, <strong>Agency address</strong>, <strong>Agent&#39;s email</strong>, <strong>Agent&#39;s phone</strong>, which replaces your contact block on the title page once it has a name; <strong>remove</strong> takes it off.</p><p><strong>Pen names</strong>: each pen name with the stories that use it, a <strong>surname</strong> field for running headers (the last word by default), <strong>default</strong> or <strong>make default</strong>, and <strong>Remove</strong>. <strong>Add pen name</strong> adds one. With none, stories are published under your legal name. Each story picks its pen name in its Export section. See <a href="/guide/guide/export">Export</a>.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p>&quot;Theme and size change the interface only. What each color means is fixed; color-blind colors change a shade or a shape, never a meaning.&quot; This computer only.</p><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Language of the app</strong></td><td><strong>Follow the system</strong> (with the language it resolves to)</td><td>Menus, labels and the desk&#39;s sentences. Choices: English (United States), English (United Kingdom), English (Canada), Português (Brasil), Português (Portugal)</td></tr></tbody></table><p>Leathercase keeps three languages apart, because a writer&#39;s machine, story and book often differ:</p><table tabindex="0"><thead><tr><th>Language</th><th>What it decides</th><th>Where it is set</th></tr></thead><tbody><tr><td>The app&#39;s</td><td>Menus, labels, the desk&#39;s sentences, dates and numbers</td><td>Here, on this computer</td></tr><tr><td>The story&#39;s</td><td>Which rules read the prose: the tagger, the style checks, the pronouns</td><td>The story&#39;s settings, kept with the story; told from the prose when not set</td></tr><tr><td>The book&#39;s</td><td>The words an export writes into the manuscript: &quot;Contents&quot;, &quot;Chapter One&quot;, the title page</td><td>Follows the story&#39;s language</td></tr></tbody></table><p>A writer can run the app in Portuguese on a story written in English. See <a href="/guide/reference/languages">Languages</a>.</p><h3 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Mode</strong></td><td><strong>Match system</strong></td><td><strong>Dark</strong>, <strong>Light</strong> or <strong>Match system</strong>, which follows the desktop. Also the commands <strong>Theme: light</strong>, <strong>Theme: dark</strong>, <strong>Theme: follow the desktop</strong></td></tr></tbody></table><h3 id="manuscript-view" tabindex="-1">Manuscript view <a class="header-anchor" href="#manuscript-view" aria-label="Permalink to &quot;Manuscript view&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Prose size</strong></td><td>16 px</td><td>The size of the manuscript&#39;s text, 14 to 20 px</td></tr><tr><td><strong>Line length</strong></td><td>Medium</td><td><strong>Narrow</strong> (58), <strong>Medium</strong> (66) or <strong>Wide</strong> (76) characters per line</td></tr><tr><td><strong>Page face</strong></td><td>Instrument Sans</td><td>The manuscript&#39;s prose: Instrument Sans, Literata, Georgia, or <strong>Your system serif</strong>. The interface is always Instrument Sans</td></tr><tr><td><strong>Color meanings</strong></td><td>fixed</td><td>A key that draws each mark beside its meaning: <strong>Yours</strong> (vermilion), <strong>Needs checking</strong> (rose), <strong>Read from the source</strong> (dashed), <strong>Verified</strong> (green), <strong>Waiting</strong> (amber). The same in both themes. <strong>Color-blind colors</strong> beside it opens Accessibility</td></tr></tbody></table><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>&quot;How large the app is drawn, how much contrast it has, which colors mark the meanings and whether things move.&quot; This computer only.</p><h3 id="size" tabindex="-1">Size <a class="header-anchor" href="#size" aria-label="Permalink to &quot;Size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Zoom</strong></td><td>100%</td><td>The whole window, words and controls together, from 50% to 300%. Also <strong>Zoom in</strong> (<code>Ctrl+=</code>), <strong>Zoom out</strong> (<code>Ctrl+-</code>) and <strong>Actual size</strong> in the View menu</td></tr><tr><td><strong>Prose size</strong></td><td>16 px</td><td>The manuscript&#39;s text, on top of the zoom. The same setting as under Appearance</td></tr></tbody></table><h3 id="seeing-and-motion" tabindex="-1">Seeing and motion <a class="header-anchor" href="#seeing-and-motion" aria-label="Permalink to &quot;Seeing and motion&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Stronger contrast</strong></td><td>Off</td><td>Darker secondary text and borders, in both themes</td></tr><tr><td><strong>Color-blind colors</strong></td><td>Off</td><td>Verified turns blue instead of green; needs checking becomes a diamond and waiting a triangle, so neither rests on its color alone. Made for red-green and blue-yellow color blindness. Every meaning stays the same</td></tr><tr><td><strong>Reduce motion</strong></td><td>Off</td><td>No fades</td></tr></tbody></table><p>Reset this section puts these four back and leaves the prose size alone.</p><h2 id="lenses" tabindex="-1">Lenses <a class="header-anchor" href="#lenses" aria-label="Permalink to &quot;Lenses&quot;">​</a></h2><p>&quot;One lens at a time on the manuscript page.&quot; This computer only. See <a href="/guide/guide/lenses">Lenses and style checks</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Rhythm tiers</strong></td><td>6</td><td>How many bands of sentence length, cool to warm, 4 to 6</td></tr><tr><td><strong>Style checks</strong></td><td>All on</td><td>Which kinds the style lens tints: adverb, passive, filter, cliché, repetition, metaphor, nominalization, weak verb. Off is off everywhere</td></tr><tr><td><strong>Echo sensitivity</strong></td><td>Medium</td><td><strong>Low</strong>, <strong>Medium</strong> or <strong>High</strong>: how close two passages must be before the echo lens marks them</td></tr></tbody></table><h2 id="manuscript" tabindex="-1">Manuscript <a class="header-anchor" href="#manuscript" aria-label="Permalink to &quot;Manuscript&quot;">​</a></h2><p>&quot;How the notes become one book. The files are read as they are; only the page changes.&quot; This computer only. See <a href="/guide/guide/manuscript">Manuscript</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Folder levels as headings</strong></td><td>2</td><td>How many folder levels become headings above the notes; 0 for none</td></tr><tr><td><strong>Note names as headings</strong></td><td>On</td><td>A note&#39;s name becomes a heading above its text</td></tr><tr><td><strong>Strip from names</strong></td><td>Numbers and separators</td><td>Sort prefixes such as <code>01 - </code> are dropped from folder and note names; or <strong>Nothing</strong></td></tr><tr><td><strong>Reading speed</strong></td><td>250</td><td>Words a minute, for the reading time on the page, 100 to 600</td></tr></tbody></table><h2 id="new-stories" tabindex="-1">New stories <a class="header-anchor" href="#new-stories" aria-label="Permalink to &quot;New stories&quot;">​</a></h2><p>&quot;What a new story starts with. Each story keeps its own target, deadline and daily goal in its settings.&quot; This computer only.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Daily goal for a new story</strong></td><td>500</td><td>Words a day, 0 to 5,000; 0 means no goal, and any day with new words counts</td></tr></tbody></table><h2 id="kind-colours" tabindex="-1">Kind colours <a class="header-anchor" href="#kind-colours" aria-label="Permalink to &quot;Kind colours&quot;">​</a></h2><p>&quot;The colour each kind of name wears across the app: in the Tags view, the Characters view and every list of names. The Graph tells kinds apart by shape, so its colour stays with what you made.&quot; This computer only.</p><p><strong>Kinds and colors</strong>: a colour for each kind: Characters, Places, Items, Factions, Events, References, Chapters, Names without a note. Click the swatch to pick a colour (&quot;#3a7bd5 · yours&quot;); <strong>theme&#39;s</strong> returns it to the theme&#39;s colour. A story&#39;s own kinds take the story&#39;s colours.</p><h2 id="the-mate" tabindex="-1">The mate <a class="header-anchor" href="#the-mate" aria-label="Permalink to &quot;The mate&quot;">​</a></h2><p>The mate&#39;s settings. &quot;The mate is Leathercase&#39;s own assistant. It reads your stories with Leathercase&#39;s rules, on this computer, and wakes no model.&quot; This computer only (<code>preferences.json</code>, and what it told in <code>mate/</code>). See <a href="/guide/guide/mate">The mate</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Heartbeat</strong></td><td>On</td><td>Looks after a save, every half hour, and when you ask</td></tr></tbody></table><p><img src="'+h+'" alt="Settings › The mate with the heartbeat on, the rules it watches, and the model turns drawn greyed" width="538" height="1100" loading="lazy"></p><p><strong>What it watches</strong>: a switch per rule, each &quot;watched&quot; or &quot;muted&quot;: <strong>Thread stops that lost their quote</strong>, <strong>Scenes with no point of view</strong>, <strong>Scenes with no beat</strong>, <strong>Plants with no payoff</strong>, <strong>Changesets gone stale</strong>, <strong>Stops that link to no scene</strong>, <strong>Pace behind the goal</strong>, <strong>Characters with no pronoun</strong>, <strong>Echoes</strong>, <strong>Style findings</strong>. All on by default.</p><p><strong>How it tells you</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Notifications</strong></td><td>In the app</td><td><strong>Off</strong>, <strong>In the app</strong>, or <strong>Also the system, when away</strong>. &quot;Never a sound. The system only when the window is in the background, at most once every three hours.&quot;</td></tr><tr><td><strong>What may reach the system</strong></td><td>Changesets gone stale, Pace behind the goal, Thread stops that lost their quote</td><td>Shown with <strong>Also the system, when away</strong>: a switch per rule</td></tr><tr><td><strong>Quiet hours</strong></td><td>22:00 to 08:00</td><td>Shown with <strong>Also the system, when away</strong>: <strong>From</strong> and <strong>To</strong>, or <strong>None</strong>. No system notification between these times</td></tr><tr><td><strong>Next steps</strong></td><td>On</td><td>One suggestion at a time, from commands not tried yet, never while you type</td></tr></tbody></table><p><strong>Model turns</strong>: &quot;Model turns come with a later paid service. Until then the mate wakes no model.&quot;</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>When it may wake a model</strong></td><td>Off</td><td><strong>Off</strong>, <strong>On request</strong>, <strong>On schedule</strong>: drawn greyed, and cannot be changed in the free app</td></tr><tr><td><strong>Daily cap</strong></td><td>50 model calls and $1.00 a day</td><td>Shown for reference; not in use</td></tr><tr><td><strong>Use your own agent</strong></td><td></td><td>&quot;Claude Code, Codex or Claude Desktop, connected in Agents, can read and propose through Leathercase today.&quot; <strong>Connect an agent</strong> opens Agents › Connect</td></tr></tbody></table><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>&quot;Word search always works. Meaning search finds passages in other words, with a model that runs on this computer.&quot; This computer only (<code>preferences.json</code>, and the model in <code>models/</code>).</p><table tabindex="0"><thead><tr><th>Field</th><th>What it shows or does</th></tr></thead><tbody><tr><td><strong>Meaning search</strong></td><td>Its state: &quot;Not on this computer.&quot;, &quot;Downloading: 42%.&quot;, &quot;Paused at 42%.&quot;, &quot;The download did not finish.&quot;, or &quot;On this computer: Xenova/multilingual-e5-small, 135 MB.&quot; Buttons: <strong>Download, 135 MB</strong> (or <strong>Resume</strong>), <strong>Pause</strong> while downloading, <strong>Cancel</strong> while downloading or paused, <strong>Remove</strong> once it is here</td></tr></tbody></table><p>Before the download, a faint line names the model, its licence (MIT), its size, and &quot;checked before use&quot;. On an Intel Mac it says &quot;This computer cannot run it: there is no runtime for Intel Macs. Word search works as always.&quot; See <a href="/guide/guide/mate#meaning-search">The mate › Meaning search</a>.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>The programs on this computer that read your stories through Leathercase: the list of agents, <strong>Connect an agent</strong>, each agent&#39;s <strong>Log</strong>, <strong>Edit grant</strong> and <strong>Revoke</strong>, and <strong>Pause all agents</strong>. This computer only (<code>agents.json</code> and <code>agents/</code>); the agents&#39; logs live with the stories. The section shows the number of agents connected, and an amber dot when there are refusals you have not seen. Everything is described in <a href="/guide/guide/connect-an-agent">Connect an agent</a>.</p><h2 id="hotkeys" tabindex="-1">Hotkeys <a class="header-anchor" href="#hotkeys" aria-label="Permalink to &quot;Hotkeys&quot;">​</a></h2><p>&quot;Every command and its key.&quot; Rebind or unbind any of them in <code>keybindings.json</code>, which holds your changes only; every default is listed beside it in <code>keybindings.defaults.json</code>. Writes <code>keybindings.json</code> and <code>preferences.json</code>, on this computer only. See <a href="/guide/reference/keys">Keys and commands</a>.</p><p><strong>Anywhere on this computer</strong>: the two keys that work when another app is in front, <strong>off by default</strong>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Capture to Writer</strong></td><td><code>Ctrl+Shift+N</code></td><td>Opens a small window over any app; what you type lands in the Writer&#39;s Ideas</td></tr><tr><td><strong>Show Leathercase</strong></td><td><code>Ctrl+Shift+S</code></td><td>Brings Leathercase forward from any app</td></tr></tbody></table><p><strong>Turn on global keys</strong> (or <strong>Turn off global keys</strong>) sits on the group&#39;s heading. Click a key&#39;s field and press the new keys to change it (setting a key also turns the global keys on). A row says &quot;Off.&quot; while they are off, and in amber when another app holds the key or the system cannot hold it.</p><p><strong>In the app</strong>: every command, its id in grey, and its key (&quot;—&quot; for none). <strong>Edit keybindings.json</strong> opens the file in your text editor; your changes there apply the next time Leathercase starts.</p><p>A note at the foot: &quot;The keys that work anywhere are this computer&#39;s and live in its preferences.json; the rest are in keybindings.json. ? shows the keys of any view; Ctrl K finds anything.&quot;</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>&quot;Leathercase goes online for one thing only, to ask which version is newest, and only when you say so. Nothing about you or your writing is sent.&quot; This computer only. See <a href="/guide/reference/updates">Updates and uninstalling</a>.</p><table tabindex="0"><thead><tr><th>Row</th><th>Default</th><th>What it shows or does</th></tr></thead><tbody><tr><td><strong>This version</strong></td><td></td><td>The copy installed on this computer</td></tr><tr><td><strong>Check when Leathercase opens</strong></td><td>Off</td><td>Off until you turn it on. When a newer version is out, a dot on Settings says so; nothing downloads by itself</td></tr><tr><td><strong>Newer version</strong></td><td></td><td>Where this copy stands, with one action (see below)</td></tr><tr><td><strong>Uninstall</strong></td><td></td><td><strong>How to uninstall</strong> opens the guide to what uninstalling removes on Windows, macOS and Linux; <strong>Back to Settings</strong> or <code>Esc</code> returns</td></tr></tbody></table><p>The <strong>Newer version</strong> row says one of:</p><table tabindex="0"><thead><tr><th>It says</th><th>Button</th></tr></thead><tbody><tr><td>&quot;Not checked since Leathercase opened.&quot;</td><td><strong>Check now</strong></td></tr><tr><td>&quot;Asking the releases…&quot;</td><td>none</td></tr><tr><td>&quot;This is the newest version. Checked at 14:02 UTC.&quot;</td><td><strong>Check again</strong></td></tr><tr><td>&quot;Version 0.25.0 is out. It downloads now and installs when you restart.&quot;</td><td><strong>Download</strong></td></tr><tr><td>&quot;Version 0.25.0 is out. This copy cannot replace itself, so its download page opens.&quot;</td><td><strong>Open download page</strong></td></tr><tr><td>&quot;Downloading version 0.25.0…&quot;</td><td>none</td></tr><tr><td>&quot;Version 0.25.0 is downloaded. It installs when you restart, or the next time you quit.&quot;</td><td><strong>Restart now</strong></td></tr><tr><td>The reason a check failed</td><td><strong>Try again</strong></td></tr><tr><td>&quot;A build run from source does not check.&quot;</td><td>none</td></tr></tbody></table><p>The command <strong>Check for updates</strong> opens this section and checks at once. When a newer version is out, a dot also appears beside <strong>Settings</strong> in the sidebar.</p><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>What Leathercase is, and which copy you have: the Le and the wordmark, &quot;Carry every story.&quot;, a line on what the app does, this copy&#39;s version with the same newer-version row as Updates, a link to <strong>Every version and its notes</strong> (the releases page, in your browser), and the copyright. It writes nothing and goes online only when you press <strong>Check now</strong>.</p><p><strong>About Leathercase</strong> opens it from the app menu on macOS, from <strong>Help</strong> on Windows and Linux, and from the find field anywhere.</p><h2 id="story-›-structure-and-goals" tabindex="-1">Story › Structure and goals <a class="header-anchor" href="#story-›-structure-and-goals" aria-label="Permalink to &quot;Story › Structure and goals&quot;">​</a></h2><p>&quot;A story&#39;s settings travel with it: its files, its structure and plot columns, its goals, its dialogue marks.&quot; The row <strong>Structure, goals and checks</strong> shows the story&#39;s folder and the patterns that pick its files, and <strong>Open the story&#39;s settings</strong> opens its settings page beside the story. Kept in the story&#39;s <code>suite/Story.json</code>. See <a href="/guide/guide/story-settings">Story settings</a>.</p><h2 id="story-›-export" tabindex="-1">Story › Export <a class="header-anchor" href="#story-›-export" aria-label="Permalink to &quot;Story › Export&quot;">​</a></h2><p>The picked story&#39;s export settings, titled &quot;The Lamp at Ferrol · Export&quot;: <strong>File</strong> (PDF, Word, EPUB, Markdown, or Fountain for a script), <strong>Paper</strong>, <strong>Font</strong>, <strong>Title page</strong>, <strong>Byline</strong> (the story&#39;s pen name), <strong>Running header</strong>, <strong>Header keyword</strong>, <strong>Chapters</strong>, <strong>Parts</strong>, <strong>Chapter headings</strong>, <strong>Scene break</strong>, and the word count. The book&#39;s own words follow the story&#39;s language. Kept in the story&#39;s <code>suite/Export.json</code>. See <a href="/guide/guide/export">Export</a>.</p><h2 id="settings-found-elsewhere" tabindex="-1">Settings found elsewhere <a class="header-anchor" href="#settings-found-elsewhere" aria-label="Permalink to &quot;Settings found elsewhere&quot;">​</a></h2><p>A few settings live beside what they change, not on this page:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where</th></tr></thead><tbody><tr><td>The folder your Writer cards go in (the home&#39;s author data folder)</td><td>The Writer Board&#39;s side column, <strong>Your cards go in</strong>, with <strong>Choose…</strong> and <strong>Use the default</strong>; see <a href="/guide/guide/writer-board">The Writer Board</a></td></tr><tr><td>The folder a story&#39;s own suite files go in</td><td>The story&#39;s settings, <strong>Leathercase&#39;s files go in</strong>; see <a href="/guide/guide/story-settings">Story settings</a></td></tr><tr><td>A story&#39;s language, goals, deadline, plot columns and dialogue marks</td><td>The story&#39;s settings</td></tr><tr><td>What a graph tab shows for a story</td><td>The Graph&#39;s side column, kept in the tab&#39;s file</td></tr><tr><td>Whether the assistant&#39;s layer is shown</td><td><code>Ctrl+.</code> on any view; remembered on this computer</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/reference/keys">Keys and commands</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/languages">Languages</a></li><li><a href="/guide/reference/updates">Updates and uninstalling</a></li><li><a href="/guide/guide/mate">The mate</a>, <a href="/guide/guide/connect-an-agent">Connect an agent</a></li></ul>',115)])])}const w=e(i,[["render",g]]);export{f as __pageData,w as default};
